import { api_call_post, api_call_get } from './index';
import type { Option } from './types';

const prefix = 'trees/';

function api_call_post_tree(path: string, body: unknown) {
	return api_call_post(prefix + path, body);
}

function api_call_get_tree(path: string) {
	return api_call_get(prefix + path);
}

/** The general data of the tree, NOT including the structure or autogenerated data */
type TreeData = {
	title: string;
	description: Option<string>;
	book_name: Option<string>;
	book_edition: Option<string>;
	book_isbn: Option<string>;
	book_chapter: Option<string>;
	book_exercise: Option<string>;
	assignment_text: Option<string>;
};

type TreeId = number;

/** Add a tree to the database */
export function add_tree(tree: TreeData): Promise<TreeId> {
	return api_call_post_tree('add_new_tree', tree);
}
